 const hooks: ContextHooks = {
   baseball: "Run differential: down 4 runs, score 7 — net is +3.",
   softball: "sb hook",
@@ -66,7 +76,10 @@ describe("RuleBasedTutor", () => {
       node,
       "baseball",
     );
+    expect(response.reframe).toContain("The core idea, in ");
